//! Table editor: change columns, keys, indexes and comments; the ALTER
//! script is generated by diffing against the table as loaded, using the
//! same structural diff as schema compare.

use egui::{RichText, Ui};
use pythia_compare::script::{ScriptHeader, render};
use pythia_compare::table::{
    ColumnDef, ConstraintDef, ConstraintKind, IndexDef, TableDef, diff, load,
};
use pythia_db::oracle::Connection;
use pythia_db::{DbEvent, DbRequest};
use serde::{Deserialize, Serialize};

use crate::documents::{DocContext, Effects, ObjectRef, OpenRequest, Target, request_id};

#[derive(Serialize, Deserialize)]
pub struct TableEditor {
    pub object: ObjectRef,
    #[serde(skip)]
    state: State,
}

#[derive(Default)]
struct State {
    loading: Option<u64>,
    original: Option<TableDef>,
    edited: Option<TableDef>,
    error: Option<String>,
    tab: Tab,
    allow_drops: bool,
    new_index: (String, bool, String),
    new_constraint: (String, ConstraintKindChoice, String),
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
enum Tab {
    #[default]
    Columns,
    Keys,
    Indexes,
    Script,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
enum ConstraintKindChoice {
    #[default]
    Unique,
    Primary,
    Check,
}

impl TableEditor {
    pub fn new(object: ObjectRef) -> Self {
        Self {
            object,
            state: State::default(),
        }
    }

    pub fn title(&self) -> String {
        let dirty = if self.is_dirty() { " •" } else { "" };
        format!("{} (edit){dirty}", self.object.name.to_lowercase())
    }

    pub fn is_busy(&self) -> bool {
        self.state.loading.is_some()
    }

    pub fn is_dirty(&self) -> bool {
        matches!((&self.state.original, &self.state.edited), (Some(a), Some(b)) if a != b)
    }

    pub fn load(&mut self) -> Effects {
        let mut effects = Effects::default();
        let (owner, name) = (self.object.owner.clone(), self.object.name.clone());
        let id = request_id();
        self.state.loading = Some(id);
        self.state.error = None;
        let task: pythia_db::TaskFn = Box::new(move |conn: &Connection| {
            let mut tables = load(conn, &owner, Some(&name)).map_err(pythia_db::DbError::from)?;
            let table = tables.remove(&name).ok_or_else(|| {
                pythia_db::DbError::new(format!("Table {owner}.{name} not found"))
            })?;
            Ok(Box::new(table) as Box<dyn std::any::Any + Send>)
        });
        effects.request(Target::Main, DbRequest::Task { id, task });
        effects
    }

    pub fn on_event(&mut self, event: DbEvent) -> Effects {
        if let DbEvent::TaskDone { id, result } = event
            && self.state.loading == Some(id)
        {
            self.state.loading = None;
            match result.map(|any| any.downcast::<TableDef>()) {
                Ok(Ok(table)) => {
                    self.state.edited = Some((*table).clone());
                    self.state.original = Some(*table);
                }
                Ok(Err(_)) => self.state.error = Some("unexpected result".into()),
                Err(e) => self.state.error = Some(e.to_string()),
            }
        }
        Effects::default()
    }

    /// The ALTER script turning the loaded table into the edited one.
    fn script(&self) -> (String, Vec<String>) {
        let (Some(original), Some(edited)) = (&self.state.original, &self.state.edited) else {
            return (String::new(), Vec::new());
        };
        let d = diff(edited, original, self.state.allow_drops);
        let header = ScriptHeader {
            title: format!(
                "Changes to {}.{} (generated by Pythia)",
                self.object.owner, self.object.name
            ),
            schema: Some(self.object.owner.clone()),
            recompile: false,
        };
        (
            if d.is_empty() {
                String::new()
            } else {
                render(&header, &d.statements)
            },
            d.notes,
        )
    }

    pub fn ui(&mut self, ui: &mut Ui, cx: &DocContext) -> Effects {
        let mut effects = Effects::default();
        if let Some(e) = &self.state.error {
            ui.colored_label(ui.visuals().error_fg_color, e);
            if ui.button("Retry").clicked() {
                effects.extend(self.load());
            }
            return effects;
        }
        if self.state.edited.is_none() {
            ui.spinner();
            return effects;
        }
        let (script, notes) = self.script();
        ui.horizontal(|ui| {
            ui.label(RichText::new(format!("{}.{}", self.object.owner, self.object.name)).strong());
            ui.separator();
            ui.selectable_value(&mut self.state.tab, Tab::Columns, "Columns");
            ui.selectable_value(&mut self.state.tab, Tab::Keys, "Keys & checks");
            ui.selectable_value(&mut self.state.tab, Tab::Indexes, "Indexes");
            let label = if script.is_empty() {
                "Script".to_owned()
            } else {
                "Script •".to_owned()
            };
            ui.selectable_value(&mut self.state.tab, Tab::Script, label);
            ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                let can_apply = !script.is_empty() && cx.connected;
                if ui
                    .add_enabled(
                        can_apply,
                        egui::Button::image_and_text(
                            pythia_ui::icons::Icon::Execute.image(ui),
                            "Apply…",
                        ),
                    )
                    .on_hover_text("Opens the script in a SQL window and runs it there")
                    .clicked()
                    && let Some(connection) = cx.connection.clone()
                {
                    effects.open.push(OpenRequest::Sql {
                        connection,
                        text: script.clone(),
                        run: true,
                    });
                }
                if ui
                    .add_enabled(self.is_dirty(), egui::Button::new("Revert"))
                    .clicked()
                {
                    self.state.edited = self.state.original.clone();
                }
                if ui.button("Reload").clicked() {
                    effects.extend(self.load());
                }
            });
        });
        ui.separator();
        let table = self.state.edited.as_mut().expect("loaded");
        match self.state.tab {
            Tab::Columns => columns_ui(ui, table),
            Tab::Keys => keys_ui(ui, table, &mut self.state.new_constraint),
            Tab::Indexes => indexes_ui(ui, table, &mut self.state.new_index),
            Tab::Script => {
                ui.checkbox(&mut self.state.allow_drops, "Allow dropping columns")
                    .on_hover_text("Dropping columns loses data; off by default");
                for note in &notes {
                    ui.colored_label(ui.visuals().warn_fg_color, note);
                }
                if script.is_empty() {
                    ui.weak("No changes");
                } else {
                    egui::ScrollArea::both().auto_shrink(false).show(ui, |ui| {
                        ui.add(egui::Label::new(RichText::new(&script).monospace()).extend());
                    });
                }
            }
        }
        effects
    }
}

fn columns_ui(ui: &mut Ui, table: &mut TableDef) {
    ui.horizontal(|ui| {
        ui.label("Table comment");
        let mut comment = table.comment.clone().unwrap_or_default();
        if ui
            .add_sized([480.0, 22.0], egui::TextEdit::singleline(&mut comment))
            .changed()
        {
            table.comment = Some(comment).filter(|c| !c.is_empty());
        }
    });
    ui.add_space(6.0);
    let mut remove = None;
    egui::ScrollArea::vertical()
        .auto_shrink([false, true])
        .max_height(ui.available_height() - 40.0)
        .show(ui, |ui| {
            egui::Grid::new("table-columns")
                .striped(true)
                .num_columns(6)
                .spacing([10.0, 4.0])
                .show(ui, |ui| {
                    for title in ["Name", "Type", "Null", "Default", "Comment", ""] {
                        ui.strong(title);
                    }
                    ui.end_row();
                    for (i, col) in table.columns.iter_mut().enumerate() {
                        ui.add_sized(
                            [180.0, 22.0],
                            egui::TextEdit::singleline(&mut col.name)
                                .font(egui::TextStyle::Monospace),
                        );
                        ui.add_sized(
                            [170.0, 22.0],
                            egui::TextEdit::singleline(&mut col.data_type)
                                .font(egui::TextStyle::Monospace),
                        );
                        ui.checkbox(&mut col.nullable, "");
                        let mut default = col.default.clone().unwrap_or_default();
                        if ui
                            .add_sized(
                                [140.0, 22.0],
                                egui::TextEdit::singleline(&mut default)
                                    .font(egui::TextStyle::Monospace),
                            )
                            .changed()
                        {
                            col.default = Some(default).filter(|d| !d.trim().is_empty());
                        }
                        let mut comment = col.comment.clone().unwrap_or_default();
                        if ui
                            .add_sized([260.0, 22.0], egui::TextEdit::singleline(&mut comment))
                            .changed()
                        {
                            col.comment = Some(comment).filter(|c| !c.is_empty());
                        }
                        if crate::icons_ext::small_icon_button(
                            ui,
                            pythia_ui::icons::Icon::Trash,
                            "Remove column",
                        )
                        .clicked()
                        {
                            remove = Some(i);
                        }
                        ui.end_row();
                    }
                });
        });
    if let Some(i) = remove {
        table.columns.remove(i);
    }
    if pythia_ui::icons::icon_text_button(ui, pythia_ui::icons::Icon::Plus, "Add column").clicked()
    {
        table.columns.push(ColumnDef {
            name: format!("NEW_COLUMN_{}", table.columns.len() + 1),
            data_type: "VARCHAR2(100 CHAR)".into(),
            nullable: true,
            default: None,
            comment: None,
        });
    }
    ui.label(RichText::new("Renaming a column is generated as drop + add; use ALTER TABLE … RENAME COLUMN for data-preserving renames.").small().weak());
}

fn keys_ui(ui: &mut Ui, table: &mut TableDef, new: &mut (String, ConstraintKindChoice, String)) {
    let mut remove = None;
    egui::Grid::new("table-keys")
        .striped(true)
        .num_columns(4)
        .spacing([12.0, 4.0])
        .show(ui, |ui| {
            for title in ["Name", "Type", "Definition", ""] {
                ui.strong(title);
            }
            ui.end_row();
            for (i, c) in table.constraints.iter().enumerate() {
                ui.label(RichText::new(&c.name).monospace());
                ui.label(format!("{:?}", c.kind));
                let def = match (&c.kind, &c.references, &c.condition) {
                    (ConstraintKind::Foreign, Some((t, cols)), _) => {
                        format!("({}) → {t} ({})", c.columns.join(", "), cols.join(", "))
                    }
                    (ConstraintKind::Check, _, Some(cond)) => cond.clone(),
                    _ => format!("({})", c.columns.join(", ")),
                };
                ui.label(RichText::new(def).monospace());
                if crate::icons_ext::small_icon_button(
                    ui,
                    pythia_ui::icons::Icon::Trash,
                    "Drop constraint",
                )
                .clicked()
                {
                    remove = Some(i);
                }
                ui.end_row();
            }
        });
    if let Some(i) = remove {
        table.constraints.remove(i);
    }
    ui.add_space(8.0);
    ui.horizontal(|ui| {
        ui.label("New");
        ui.add(
            egui::TextEdit::singleline(&mut new.0)
                .hint_text("name")
                .desired_width(160.0),
        );
        egui::ComboBox::from_id_salt("new-constraint-kind")
            .selected_text(format!("{:?}", new.1))
            .show_ui(ui, |ui| {
                ui.selectable_value(&mut new.1, ConstraintKindChoice::Unique, "Unique");
                ui.selectable_value(&mut new.1, ConstraintKindChoice::Primary, "Primary");
                ui.selectable_value(&mut new.1, ConstraintKindChoice::Check, "Check");
            });
        let hint = if new.1 == ConstraintKindChoice::Check {
            "condition, e.g. salary > 0"
        } else {
            "columns, e.g. a, b"
        };
        ui.add(
            egui::TextEdit::singleline(&mut new.2)
                .hint_text(hint)
                .desired_width(260.0),
        );
        if ui
            .add_enabled(
                !new.0.trim().is_empty() && !new.2.trim().is_empty(),
                egui::Button::new("Add"),
            )
            .clicked()
        {
            let (kind, columns, condition) = match new.1 {
                ConstraintKindChoice::Check => (
                    ConstraintKind::Check,
                    Vec::new(),
                    Some(new.2.trim().to_owned()),
                ),
                ConstraintKindChoice::Primary => {
                    (ConstraintKind::Primary, split_columns(&new.2), None)
                }
                ConstraintKindChoice::Unique => {
                    (ConstraintKind::Unique, split_columns(&new.2), None)
                }
            };
            table.constraints.push(ConstraintDef {
                name: new.0.trim().to_uppercase(),
                kind,
                columns,
                references: None,
                on_delete: None,
                condition,
                generated: false,
            });
            *new = Default::default();
        }
    });
}

fn indexes_ui(ui: &mut Ui, table: &mut TableDef, new: &mut (String, bool, String)) {
    let mut remove = None;
    egui::Grid::new("table-indexes")
        .striped(true)
        .num_columns(4)
        .spacing([12.0, 4.0])
        .show(ui, |ui| {
            for title in ["Name", "Unique", "Columns", ""] {
                ui.strong(title);
            }
            ui.end_row();
            for (i, idx) in table.indexes.iter().enumerate() {
                ui.label(RichText::new(&idx.name).monospace());
                ui.label(if idx.unique { "yes" } else { "" });
                ui.label(RichText::new(idx.columns.join(", ")).monospace());
                if crate::icons_ext::small_icon_button(
                    ui,
                    pythia_ui::icons::Icon::Trash,
                    "Drop index",
                )
                .clicked()
                {
                    remove = Some(i);
                }
                ui.end_row();
            }
        });
    if let Some(i) = remove {
        table.indexes.remove(i);
    }
    ui.add_space(8.0);
    ui.horizontal(|ui| {
        ui.label("New");
        ui.add(
            egui::TextEdit::singleline(&mut new.0)
                .hint_text("name")
                .desired_width(160.0),
        );
        ui.checkbox(&mut new.1, "Unique");
        ui.add(
            egui::TextEdit::singleline(&mut new.2)
                .hint_text("columns, e.g. last_name, first_name")
                .desired_width(300.0),
        );
        if ui
            .add_enabled(
                !new.0.trim().is_empty() && !new.2.trim().is_empty(),
                egui::Button::new("Add"),
            )
            .clicked()
        {
            table.indexes.push(IndexDef {
                name: new.0.trim().to_uppercase(),
                unique: new.1,
                columns: split_columns(&new.2),
                generated: false,
            });
            *new = Default::default();
        }
    });
}

fn split_columns(text: &str) -> Vec<String> {
    text.split(',')
        .map(|c| c.trim().to_uppercase())
        .filter(|c| !c.is_empty())
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn script_from_edits() {
        let original = TableDef {
            name: "EMP".into(),
            columns: vec![ColumnDef {
                name: "ID".into(),
                data_type: "NUMBER(10)".into(),
                nullable: false,
                default: None,
                comment: None,
            }],
            comment: None,
            constraints: Vec::new(),
            indexes: Vec::new(),
        };
        let mut editor = TableEditor::new(ObjectRef {
            owner: "HR".into(),
            name: "EMP".into(),
            object_type: pythia_db::ObjectType::Table,
        });
        editor.state.original = Some(original.clone());
        let mut edited = original;
        edited.columns.push(ColumnDef {
            name: "NAME".into(),
            data_type: "VARCHAR2(30 CHAR)".into(),
            nullable: true,
            default: None,
            comment: Some("Full name".into()),
        });
        editor.state.edited = Some(edited);
        assert!(editor.is_dirty());
        let (script, _) = editor.script();
        assert!(script.to_lowercase().contains("add"), "{script}");
        assert!(script.contains("add (name VARCHAR2(30 CHAR))"), "{script}");
        assert!(
            script.to_lowercase().contains("comment on column"),
            "{script}"
        );
    }
}
